from urllib.parse import unquote


def _decode(text):
    return unquote(text.replace("+", " "))


def parse_query(qs):
    qs = qs[1:] if qs[:1] == "?" else qs
    pairs = (p.split("=", 1) for p in qs.split("&") if p)
    return {_decode(p[0]): _decode(p[1] if len(p) > 1 else "") for p in pairs}
